swiftui.code:
// AspectRatio 는 AspectRatioBox 별칭이다 — 같은 레시피를 쓴다
// SwiftUI — 웹 <jd-aspect-ratio-box> 동형. 기본 16/9.
content
    .aspectRatio(16.0 / 9.0, contentMode: .fill)
    .clipped()                                      // 웹 overflow:hidden

uikit.code:
// AspectRatio 는 AspectRatioBox 별칭이다 — 같은 레시피를 쓴다
// UIKit — 폭·높이 제약의 배율로 비율을 고정한다
child.jd.layout { $0.width.equal(to: child.jd.height).multiplier(16.0 / 9.0) }
